import { query } from '../client.js';
function value(options, key) {
  if (!options[key] || options[key] === true) throw new Error('Provide --' + key);
  return options[key];
}
function ids(raw) {
  return String(raw).split(',').map(value => value.trim()).filter(Boolean);
}
export async function boardCommand({ args, options, client, print }) {
  const [action = 'show', id] = args;
  if (!id) throw new Error('Usage: crew board show <project-id> | move <issue-id> --status ID | bulk <project-id> --issues ID,ID');
  if (action === 'show') return print(await client.get('/projects/' + encodeURIComponent(id) + '/board' + query({ q: options.q, assigneeId: options.assignee })));
  if (action === 'move') {
    const body = { statusId: value(options, 'status') };
    if (options.before) body.beforeId = options.before;
    if (options.after) body.afterId = options.after;
    return print(await client.post('/issues/' + encodeURIComponent(id) + '/move', body));
  }
  if (action === 'bulk') {
    const changes = {};
    if (options.status) changes.statusId = options.status;
    if (options.assignee !== undefined) changes.assigneeId = options.assignee === 'none' ? null : options.assignee;
    if (options.labels !== undefined) changes.labelIds = options.labels === 'none' ? [] : ids(options.labels);
    const body = { issueIds: ids(value(options, 'issues')), changes };
    if (options['add-labels']) body.addLabelIds = ids(options['add-labels']);
    if (options['remove-labels']) body.removeLabelIds = ids(options['remove-labels']);
    return print(await client.post('/projects/' + encodeURIComponent(id) + '/issues/bulk', body));
  }
  throw new Error('Unknown board action: ' + action);
}

import { projectCommand } from './project.js';
import { boardCommand } from './board.js';
import { issueCommand } from './issue.js';
export const commands = { project: projectCommand, issue: issueCommand, board: boardCommand };

import { AppError, fields, uniqueIds, text, validation } from '@crew/shared';
import { issueInput } from '../../../../shared/src/schemas/issue.js';
import { statusesFor, publicProject } from './projects.js';
import { getIssue, listIssues, validateIssueReferences, replaceIssueLabels, emitIssue } from './issues.js';
export const RANK_STEP = 1024;
export function rankBetween(previous, next) {
  if (previous == null && next == null) return RANK_STEP;
  if (previous == null) { const rank = next - RANK_STEP; return Number.isFinite(rank) && rank < next ? rank : null; }
  if (next == null) { const rank = previous + RANK_STEP; return Number.isFinite(rank) && rank > previous ? rank : null; }
  const middle = previous + (next - previous) / 2;
  return Number.isFinite(middle) && middle > previous && middle < next ? middle : null;
}
export function orderedIssues(issues) {
  return [...issues].sort((left, right) => left.rank - right.rank || left.id.localeCompare(right.id));
}
function moveInput(value) {
  const body = fields(value, ['statusId', 'beforeId', 'afterId']);
  const result = { statusId: text(body.statusId, 'statusId', { max: 100 }) };
  for (const key of ['beforeId', 'afterId']) if (body[key] != null) result[key] = text(body[key], key, { max: 100 });
  if (result.beforeId && result.afterId) throw validation({ beforeId: 'Provide either beforeId or afterId, not both' });
  return result;
}
function bulkInput(value) {
  const body = fields(value, ['issueIds', 'changes', 'addLabelIds', 'removeLabelIds']);
  const issueIds = uniqueIds(body.issueIds, 'issueIds');
  if (!issueIds.length) throw validation({ issueIds: 'Select at least one issue' });
  const raw = fields(body.changes ?? {}, ['statusId', 'assigneeId', 'labelIds']);
  const changes = Object.keys(raw).length ? issueInput(raw, { partial: true }) : {};
  const addLabelIds = body.addLabelIds === undefined ? [] : uniqueIds(body.addLabelIds, 'addLabelIds');
  const removeLabelIds = body.removeLabelIds === undefined ? [] : uniqueIds(body.removeLabelIds, 'removeLabelIds');
  if (!Object.keys(changes).length && !addLabelIds.length && !removeLabelIds.length) throw validation({ changes: 'Provide status, assignee, or label edits' });
  if (changes.labelIds && (addLabelIds.length || removeLabelIds.length)) throw validation({ labelIds: 'Choose label replacement or add/remove edits' });
  if (addLabelIds.some(id => removeLabelIds.includes(id))) throw validation({ addLabelIds: 'A label cannot be added and removed in one edit' });
  return { issueIds, changes, addLabelIds, removeLabelIds };
}
export function registerBoards(ctx) {
  const { app, db, requireAuth, permissions } = ctx;
  function writable(req, projectId) {
    const project = permissions.assertProject(req, projectId, 'issue:write');
    if (project.archived) throw new AppError('CONFLICT', 'Archived projects are read-only', 409);
    return project;
  }
  function move(req, issueId, body) {
    const before = getIssue(ctx, issueId);
    const project = writable(req, before.projectId);
    const input = moveInput(body);
    validateIssueReferences(ctx, project.id, { statusId: input.statusId }, issueId);
    const neighbors = orderedIssues(listIssues(ctx, project.id).filter(issue => issue.statusId === input.statusId && issue.id !== issueId));
    let index = neighbors.length;
    const anchor = input.beforeId ?? input.afterId;
    if (anchor) {
      const found = neighbors.findIndex(issue => issue.id === anchor);
      if (found < 0) throw validation({ [input.beforeId ? 'beforeId' : 'afterId']: 'Anchor must be another issue in the destination column' });
      index = found + (input.afterId ? 1 : 0);
    }
    const rebalanced = [];
    const after = ctx.transaction(() => {
      let rank = rankBetween(neighbors[index - 1]?.rank, neighbors[index]?.rank);
      if (rank == null || !Number.isFinite(rank)) {
        neighbors.forEach((issue, position) => {
          rebalanced.push(getIssue(ctx, issue.id));
          issue.rank = (position + 1) * RANK_STEP;
          db.prepare('UPDATE issues SET rank=? WHERE id=?').run(issue.rank, issue.id);
        });
        rank = rankBetween(neighbors[index - 1]?.rank, neighbors[index]?.rank);
      }
      db.prepare('UPDATE issues SET status_id=?,rank=?,updated_at=? WHERE id=?').run(input.statusId, rank, ctx.now(), issueId);
      return getIssue(ctx, issueId);
    });
    for (const previous of rebalanced) emitIssue(ctx, req, 'rank_rebalanced', previous, getIssue(ctx, previous.id));
    emitIssue(ctx, req, 'moved', before, after);
    return after;
  }
  app.get('/api/v1/projects/:projectId/board', requireAuth, (req, res) => {
    const project = permissions.assertProject(req, req.params.projectId, 'project:read');
    const issues = orderedIssues(listIssues(ctx, project.id, req.query));
    res.json({
      project: publicProject(db, project),
      columns: statusesFor(db, project.id).map(status => ({ status, issues: issues.filter(issue => issue.statusId === status.id) })),
      permissions: { write: permissions.canProject(req.user.id, project.id, 'issue:write') }
    });
  });
  app.post('/api/v1/issues/:issueId/move', requireAuth, (req, res) => res.json({ issue: move(req, req.params.issueId, req.body) }));
  app.post('/api/v1/projects/:projectId/issues/bulk', requireAuth, (req, res) => {
    const project = writable(req, req.params.projectId);
    const input = bulkInput(req.body);
    const before = input.issueIds.map(id => getIssue(ctx, id));
    if (before.some(issue => issue.projectId !== project.id)) throw validation({ issueIds: 'All issues must belong to this project' });
    validateIssueReferences(ctx, project.id, { ...input.changes, labelIds: [
      ...(input.changes.labelIds ?? []), ...input.addLabelIds, ...input.removeLabelIds
    ] });
    const items = ctx.transaction(() => before.map(issue => {
      if (input.changes.statusId !== undefined && input.changes.statusId !== issue.statusId) {
        const rank = db.prepare('SELECT COALESCE(MAX(rank),0)+? AS rank FROM issues WHERE project_id=? AND status_id=?').get(RANK_STEP, project.id, input.changes.statusId).rank;
        db.prepare('UPDATE issues SET status_id=?,rank=? WHERE id=?').run(input.changes.statusId, rank, issue.id);
      }
      if (input.changes.assigneeId !== undefined) db.prepare('UPDATE issues SET assignee_id=? WHERE id=?').run(input.changes.assigneeId, issue.id);
      if (input.changes.labelIds !== undefined) replaceIssueLabels(ctx, issue.id, input.changes.labelIds);
      else if (input.addLabelIds.length || input.removeLabelIds.length) {
        const labels = new Set(issue.labels.map(label => label.id));
        input.addLabelIds.forEach(id => labels.add(id));
        input.removeLabelIds.forEach(id => labels.delete(id));
        replaceIssueLabels(ctx, issue.id, [...labels]);
      }
      db.prepare('UPDATE issues SET updated_at=? WHERE id=?').run(ctx.now(), issue.id);
      return getIssue(ctx, issue.id);
    }));
    items.forEach((issue, index) => emitIssue(ctx, req, 'bulk_updated', before[index], issue));
    res.json({ items, count: items.length });
  });
}

import { registerProjects } from './projects.js';
import { registerBoards } from './boards.js';
import { registerIssueRoutes } from './issue-routes.js';
export function registerRoutes(ctx) {
  registerProjects(ctx);
  registerIssueRoutes(ctx);
  registerBoards(ctx);
